txtadd(pname, 'gallerybarforasinglepanoPicture', %1);
addplugin(get(pname));
set(layer[%pname].zorder, 3);
set(layer[%pname].url, %2);
set(layer[%pname].align, bottomright);
set(layer[%pname].width, 90);
set(layer[%pname].height, 60);
